def copy_variant_attributes(apps, schema_editor):
    """
    Copy old ProductVariant.attributes ManyToMany data
    into the new ProductVariantAttribute table.

    Important:
    This must run before removing ProductVariant.attributes.
    """
    ProductVariant = apps.get_model("shop", "ProductVariant")
    ProductVariantAttribute = apps.get_model("shop", "ProductVariantAttribute")

    for variant in ProductVariant.objects.all().prefetch_related("attributes"):
        for attribute_value in variant.attributes.all():
            ProductVariantAttribute.objects.update_or_create(
                variant_id=variant.id,
                attribute_id=attribute_value.attribute_id,
                defaults={
                    "value_id": attribute_value.id,
                },
            )


def set_default_variants(apps, schema_editor):
    """
    Ensure each product has exactly one default active variant.

    The first active variant by price/id becomes default.
    If a product has no active variants, we do nothing.
    """
    Product = apps.get_model("shop", "Product")

    for product in Product.objects.all():
        first_variant = (
            product.variants.filter(is_active=True).order_by("price", "id").first()
        )

        if not first_variant:
            continue

        product.variants.update(is_default=False)
        first_variant.is_default = True
        first_variant.save(update_fields=["is_default"])


def normalize_main_images(apps, schema_editor):
    """
    Ensure unique main images before adding DB constraints.

    One main product image:
    - product=X
    - variant=None
    - is_main=True

    One main image per variant:
    - variant=Y
    - is_main=True
    """
    ProductImage = apps.get_model("shop", "ProductImage")

    product_ids = (
        ProductImage.objects.filter(variant__isnull=True, is_main=True)
        .values_list("product_id", flat=True)
        .distinct()
    )

    for product_id in product_ids:
        images = ProductImage.objects.filter(
            product_id=product_id,
            variant__isnull=True,
            is_main=True,
        ).order_by("display_order", "id")

        first_image = images.first()

        if first_image:
            images.exclude(id=first_image.id).update(is_main=False)

    variant_ids = (
        ProductImage.objects.filter(variant__isnull=False, is_main=True)
        .values_list("variant_id", flat=True)
        .distinct()
    )

    for variant_id in variant_ids:
        images = ProductImage.objects.filter(
            variant_id=variant_id,
            is_main=True,
        ).order_by("display_order", "id")

        first_image = images.first()

        if first_image:
            images.exclude(id=first_image.id).update(is_main=False)


